"""Report bounded backoff and polling-chain experiments without promotion."""
from pathlib import Path
import json,numpy as np
root=Path(__file__).resolve().parents[1];p=root/'artifacts/handoff-poll-nop';s=json.loads((p/'events.json').read_text())['summaries'];back=json.loads((root/'artifacts/handoff-backoff-events.json').read_text())
lines=['GPU0 polling-cost experiments; production libraries unchanged.', '', 'Experiment1: requested32/128ns nanosleep only after a failed wait test; 240 CUDA event samples/variant.']
for v,n in enumerate(['baseline','spin','sleep32','sleep128']):
 a=np.array([x for r in back['measurements'] if r['variant']==v for x in r['samples_ms']]);lines.append(f'{n:10} mean={a.mean():.6f} median={np.median(a):.6f} p95={np.percentile(a,95):.6f}ms')
lines+=['Sleep variants lose substantially; requested nanosleep durations are hints, not exact delays.', 'PTX reference: https://docs.nvidia.com/cuda/pdf/ptx_isa_8.5.pdf', '32 complete transcript+PoW digest comparisons passed, including full8192x8192 inputs.', '', 'Experiment2: source inline-PTX wait loop still compiled to6-instruction polling chain.', 'Compiled and inspected only; not benchmarked because it did not produce intended simplification.', '', 'Experiment3: retain sleep32 machine scheduling/register allocation, replace exactly one NANOSLEEP with NOP.', 'Arithmetic-preserving isolated cubin; synchronization validation unresolved; 200 CUDA event samples/variant,16 launches/sample,rotated blocks.', 'variant       mean_ms    median_ms   p95_ms']
for name,r in s.items():lines.append(f"{name:12} {r['mean_ms']:.6f}   {r['median_ms']:.6f}   {r['p95_ms']:.6f}")
b,o,n=[s[k]['mean_ms'] for k in ['baseline','spin','poll_nop']]
lines +=['',f'Short loop time reduction vs old spin={100*(1-n/o):.3f}%. Still slower than baseline by{100*(n/b-1):.3f}%.', 'Short repeated loop: NOP,LDS,LOP3(predicate),NOP,BRA. Old loop:LDS,R2UR,ULOP3,PLOP3,NOP,BRA.', 'Source readiness condition and arrivals preserved; racecheck reports hazards in the short-loop variant, so synchronization correctness is NOT established.', '168 registers/thread,zero local memory,1CTA/SM; shared69632 baseline/69640 candidates.', 'All64IMMA and16LDSM remain; no operand substitution or incorrect arithmetic.', '36 small/edge transcript comparisons PASS;8192x8192 transcript preflight passes all3 variants.', 'Memcheck2025.2.1:0errors. Racecheck2025.2.1 FAILED:30 reported error groups in poll_nop; baseline and spin emitted no hazards. Numerical equality does not establish race freedom.', 'Unpatched original sleep32 also reports the same class of shared-memory hazards in racecheck-unpatched.log. This rules out attributing the reports solely to the NOP patch; actual race versus instrumentation limitation remains unresolved. No live mining or production changes. No end-to-end throughput improvement claimed.', 'DVFS not locked; timing is diagnostic only, NOT a validated optimization.', '', 'Next step: resolve racecheck failures before further performance profiling or promotion.', 'Capture variant0=baseline,1=old spin,2=short loop (symbol still sayssleep32 but its NANOSLEEP is NOP; hashes/disassembly verify it).', 'Compare dynamic check count,IMMA/SMcycle,short-scoreboard and Tensor active utilization.', 'Do not infer checking-frequency reduction from fewer instructions per check without counters.']
(p/'report.txt').write_text('\n'.join(lines)+'\n');print('\n'.join(lines))
